"""Generate the Rust opcode lookup from local AMD RDNA 1 and RDNA 2 XMLs.

Download and unpack the XML archive linked at
https://gpuopen.com/machine-readable-isa/, then run

    python3 generate_opcodes.py DIRECTORY_CONTAINING_XML

The pinned inputs are the 2026-02-20, schema 1.1.1 specifications. All input
files are read locally. Rust code is generated in the shared native shader reader.
"""

import argparse
import hashlib
from collections import defaultdict
from pathlib import Path
from xml.etree import ElementTree


SPECS = {
    "amdgpu_isa_rdna1.xml": "f60248605e8c4cb9ae29130ce3114142467d953a3f1c57a1b0ca6d8de014e722",
    "amdgpu_isa_rdna2.xml": "d671ecbc36543674ab59e9b2feffd56718fd2137e7ad913c314f2e2508b9f4f7",
}

# All instructions with a modifier also have a base encoding, with the
# exceptions below. Global and scratch instructions have separate XML
# namespaces. The dispatcher selects their address space from the FLAT word.
FAMILIES = {
    "ENC_SOP1": "Sop1",
    "ENC_SOP2": "Sop2",
    "ENC_SOPC": "Sopc",
    "ENC_SOPK": "Sopk",
    "SOPK_INST_LITERAL": "Sopk",
    "ENC_SOPP": "Sopp",
    "ENC_SMEM": "Smem",
    "ENC_VOP1": "Vop1",
    "ENC_VOP2": "Vop2",
    "VOP2_INST_LITERAL": "Vop2",
    "ENC_VOPC": "Vopc",
    "ENC_VOP3": "Vop3",
    "VOP3_SDST_ENC": "Vop3",
    "ENC_VOP3P": "Vop3",
    "ENC_VINTRP": "Vinterp",
    "ENC_DS": "Ds",
    "ENC_FLAT": "Flat",
    "ENC_MUBUF": "Mubuf",
    "ENC_MTBUF": "Mtbuf",
    "ENC_MIMG": "Mimg",
    "ENC_EXP": "Exp",
}

HEADER = """//! Opcode names for the GFX10.1/GFX10.3 decoder.
//!
//! Generated by `generate_opcodes.py` from the 2026-02-20
//! [AMD ISA tables](https://gpuopen.com/machine-readable-isa/) (schema 1.1.1).
//! Opcode data copyright (c) 2026 Advanced Micro Devices, Inc., or its
//! affiliates, supplied under the MIT license.
//!
//! VOP3P uses dispatcher codes starting at 0x400. Xbox programs contain GFX10.1
//! and GFX10.3 instructions. For the three colliding legacy multiply-add codes
//! the translator preserves the tested GFX10.1 arithmetic. FLAT shares an opcode
//! between address spaces. Its segment field
//! selects the address space separately.

use super::Enc;

pub(super) fn lookup(enc: Enc, opcode: u32) -> Option<&'static str> {
    use Enc::*;
    Some(match (enc, opcode) {
"""


def read_opcodes(xml_path, digest):
    content = xml_path.read_bytes()
    if hashlib.sha256(content).hexdigest() != digest:
        raise ValueError(f"{xml_path} differs from the pinned AMD specification")
    codes = {}
    for instruction in ElementTree.fromstring(content).findall("./ISA/Instructions/Instruction"):
        name = instruction.findtext("InstructionName").lower()
        for entry in instruction.findall("./InstructionEncodings/InstructionEncoding"):
            encoding = entry.findtext("EncodingName")
            if encoding not in FAMILIES:
                continue
            opcode = int(entry.findtext("Opcode"))
            if encoding == "ENC_VOP3P":
                opcode += 0x400
            key = (FAMILIES[encoding], opcode)
            if codes.setdefault(key, name) != name:
                raise ValueError(f"conflicting names for {key} in {xml_path}")
    return codes


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("directory", type=Path)
    args = parser.parse_args()

    codes = {}
    for filename, digest in reversed(SPECS.items()):
        codes.update(read_opcodes(args.directory / filename, digest))
    by_name = defaultdict(list)
    for (family, opcode), name in sorted(codes.items()):
        by_name[name].append(f"({family}, {opcode})")
    arms = [f'        {" | ".join(keys)} => "{name}",' for name, keys in by_name.items()]
    source = HEADER + "\n".join(arms) + "\n        _ => return None,\n    })\n}\n"
    path = Path(__file__).resolve().parents[2] / "runtime" / "dxbc" / "src" / "rdna2" / "opcodes.rs"
    path.write_text(source, encoding="utf-8")


if __name__ == "__main__":
    main()
